//
//  SessionFixtures.kt
//  pandoracore
//
//  Shared fixtures for the SessionManager-driven test suites (the iOS
//  files duplicate these helpers per file; the Kotlin port factors them
//  once). All crypto fixtures are generated from the vendored pithos
//  Blowfish pipeline — identical vectors on both platforms.
//

package pandoracore

import java.time.Instant

/** Fixed local clock for the whole scenario (2001-09-09). */
fun fixedClock(): Instant = Instant.ofEpochSecond(1_000_000_000)

/** Encrypted syncTime fixtures (decryptKey), generated by running the
 *  vendored pithos blowfish.py + pandora_encrypt pipeline:
 *
 *  - main: plaintext "PNDS1760000000PADPAD!!" → bytes[4..<14] =
 *    "1760000000" → offset = 1760000000 − 1000000000 = 760000000
 *  - short: 8-byte plaintext → decrypts to 8 bytes < 14 → malformedSession
 *  - unparsable: bytes[4..<14] = "YYYYYYYYZZ" → Int parse fails →
 *    malformedSession */
const val SYNC_TIME_MAIN = "ac7b93e6a3c44c45258042bca01c9f6f40befffb546dee73"
const val SYNC_TIME_SHORT = "2d0462c4450f20b0"
const val SYNC_TIME_UNPARSABLE = "9778de106b6d33770f0abd434a64bd037c500805a0da4edd"

/** ok envelope; `resultObjectJSON` must already be a JSON object. */
fun okJSON(resultObjectJSON: String): Result<ByteArray> =
    Result.success("""{"stat":"ok","result":$resultObjectJSON}""".toByteArray())

/** fail envelope with proper string escaping (JSONValue.encoded). */
fun failJSON(code: kotlin.Int, message: String): Result<ByteArray> =
    Result.success(
        JSONValue.encoded(
            mapOf(
                "stat" to JSONValue.Str("fail"),
                "code" to JSONValue.Int(code.toLong()),
                "message" to JSONValue.Str(message),
            ),
        ),
    )

fun partnerOK(): Result<ByteArray> =
    okJSON("""{"partnerId":"77","partnerAuthToken":"P-TOKEN","syncTime":"$SYNC_TIME_MAIN"}""")

fun userOK(token: String = "U-TOKEN", isSubscriber: Boolean = true): Result<ByteArray> =
    okJSON("""{"userId":"u-1","userAuthToken":"$token","isSubscriber":$isSubscriber}""")

fun cachedRecord(token: String = "U-EXPIRED"): SessionRecord = SessionRecord(
    credentials = Credentials(username = "me@example.com", password = "hunter2"),
    tokens = SessionTokens(
        partnerId = "77",
        partnerAuthToken = "P-TOKEN",
        userId = "u-1",
        userAuthToken = token,
        timeOffset = 760_000_000.0,
    ),
    isSubscriber = false,
)

fun makeManager(
    transport: MockTransport,
    store: SessionStore? = null,
    modes: PandoraModesClient = PandoraModesClient(
        transport = MockModesTransport(emptyList()),
        csrf = MockCSRF(),
    ),
): SessionManager = SessionManager(
    client = LegacyPandoraClient(transport = transport),
    modes = modes,
    store = store,
    now = ::fixedClock,
)

/** Decrypts a recorded request body (hex → Blowfish-ECB → JSON) and
 *  trims the per-chunk NUL pad, for substring assertions. */
fun decryptedBody(request: MockTransport.RecordedRequest): String {
    val hex = request.body.decodeToString()
    val plain = PandoraCrypto.decryptFromHex(hex, PandoraAPI.encryptKey)
    return plain.takeWhile { it != 0.toByte() }.toByteArray().decodeToString()
}
